diagram.source:
flowchart TD
  Start[Script or module?] --> Mod{ES module?}
  Mod -->|yes| Strict[Strict mode ON]
  Mod -->|no| Dir{use strict directive?}
  Dir -->|yes| Strict
  Dir -->|no| Class{Inside class method?}
  Class -->|yes| Strict
  Class -->|no| Sloppy[Sloppy mode]

snippet.code:
// Sloppy script
function sloppy() {
  accident = 42; // creates global 'accident'
}
sloppy();
console.log(accident); // 42

'use strict';
function strict() {
  accident = 42; // ReferenceError
}

function showThis() {
  console.log(this);
}

showThis(); // sloppy: global object (window/globalThis)

'use strict';
function showThisStrict() {
  console.log(this); // undefined
}
showThisStrict();

// Sloppy: legal but confusing
function add(a, a, c) {
  return a + a + c;
}

'use strict';
// function bad(x, x) {} // SyntaxError in strict mode

// file: utils.mjs
// No 'use strict' needed
export function setCount(value) {
  undeclared = value; // ReferenceError in module
}

// Equivalent C#: compiler error CS0103 — name does not exist
